(()=>{const out=[];for(const kind of ['webgl','webgl2'])for(const options of [undefined,{}, {antialias:false}, {alpha:false,depth:false,stencil:true,premultipliedAlpha:false,preserveDrawingBuffer:true,powerPreference:'high-performance',desynchronized:true},{antialias:false,powerPreference:'low-power'}, {powerPreference:'invalid'},{alpha:0,depth:null,antialias:'',stencil:'yes',xrCompatible:true},{alpha:undefined,antialias:1,powerPreference:{toString(){return 'low-power'}}}]){try{const gl=document.createElement('canvas').getContext(kind,options);out.push({kind,options,attributes:gl?.getContextAttributes(),params:gl?[3410,3411,3412,3413,3414,3415,32936,32937].map(p=>[p,gl.getParameter(p),gl.getError()]):null})}catch(e){out.push({kind,options,error:e.name,message:e.message})}}return JSON.parse(JSON.stringify(out))})()